WITH src AS (SELECT *, COALESCE(email, 'Unknown') AS email_filled FROM employees WHERE full_name LIKE '%Henr%' AND NOT is_remote), employees_stats AS (SELECT level, DATE_TRUNC('MONTH', hire_date) AS hire_month, COUNT(CASE WHEN job_title = 'Manager' THEN 1 END) AS manager_count, SUM(salary) AS total_salary FROM src GROUP BY level, DATE_TRUNC('MONTH', hire_date)) SELECT level, hire_month, manager_count FROM employees_stats WHERE manager_count > 3 ORDER BY hire_month, level LIMIT 5;
